    uOutlineColor: [1.0, 0.55, 0.0, 1.0], // Orange selection outline
    uOutlineWidth: 0.02,
    uOpacity: 1.0,
  };

  switch (mode) {
    case "wireframe":
      return {
        ...common,
        uBaseColor: [0.0, 0.0, 0.0, 0.0],
        uRoughness: 1.0,
